 async function imageData(file,maxSize=1200,quality=.78){if(file.size>15000000)throw Error('Choose a photo under 15 MB.');const src=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('That image format could not be opened. Try a JPEG or take a new photo.'));img.src=src;});const c=document.createElement('canvas'),scale=Math.min(1,maxSize/Math.max(image.naturalWidth,image.naturalHeight));c.width=Math.max(1,Math.round(image.naturalWidth*scale));c.height=Math.max(1,Math.round(image.naturalHeight*scale));c.getContext('2d').drawImage(image,0,0,c.width,c.height);return c.toDataURL('image/jpeg',quality);}finally{URL.revokeObjectURL(src);}}
 function download(blob,name){const a=document.createElement('a'),href=URL.createObjectURL(blob);a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),60000);}
 function backup(){if(work){syncTracker();state.draft={...work,updated:new Date().toISOString()};}download(new Blob([C.backup(state)],{type:'application/json'}),'HomeScan-complete-backup-'+today()+'.json');toast('Backup downloaded. Keep it somewhere safe outside this browser.');}
